func likeMatch(text,word string)bool{
 if !strings.ContainsAny(word,"%_'"\\\\\"){return strings.Contains(text,word)}
 t:=[]rune(text);p:=[]rune(\"%\"+word+\"%\");prev:=make([]bool,len(t)+1);prev[0]=true
 for i:=0;i<len(p);i++{c:=p[i];escaped:=false;if c=='\\\\'&&i+1<len(p){i++;c=p[i];escaped=true};cur:=make([]bool,len(t)+1);if c=='%'&&"'!escaped{cur[0]=prev[0];for j:=1;j<=len(t);j++{cur[j]=prev[j]||cur[j-1]}}else{for j:=1;j<=len(t);j++{cur[j]=prev[j-1]&&(c==t[j-1]||(c=='"'_'&&"'!escaped))}};prev=cur};return prev[len(t)]
}
